// 奶蛙（Milk Frog）玩家第三人称模型：手绘 GLB（src/characters/assets/milkfrog.glb）。
// GLB 原始朝向 +Z、脚底在 y=0，这里统一转成玩家约定：朝 -Z、身高约 1.72。
//
// 这个模型是单块网格、没有骨骼，而且手臂与腰侧是连成一片的（手掌就贴在胯边，
// 沿表面从手掌走到腰侧只有 0.11，走到肩反而要 1.84）。所以不能靠顶点变形把
// 手臂抬到胸前——任何抬臂都会把肚子/腰一起撕开。这里保持模型原样，
// 只把枪放进右手（低持枪位），保证零变形、零破面。
import {
  Box3,
  Group,
  Object3D,
  Vector3,
} from "../vendor/three-r180.js";
import { GLTFLoader } from "../vendor/GLTFLoader.js";
import { createPac9Prop } from "../weapons/pac9-prop.js";

const FROG_URL = new URL("./assets/milkfrog.glb", import.meta.url).href;

// 静止姿态的右手位置（模型空间：Y 向上、+Z 朝前、身高 1.073）。
// 模型朝 +Z，所以右手在 -X 侧。
const HAND = [-0.245, 0.375, 0.03];

let templatePromise = null;

function loadTemplate() {
  if (!templatePromise) {
    templatePromise = new GLTFLoader()
      .loadAsync(FROG_URL)
      .then((gltf) => {
        const root = gltf.scene,
          box = new Box3().setFromObject(root),
          s = 1.72 / Math.max(box.max.y - box.min.y, 1e-3);
        root.traverse((o) => {
          if (!o.isMesh) return;
          o.castShadow = !0;
          o.receiveShadow = !1;
          o.frustumCulled = !1;
        });
        root.userData.gunLocal = new Vector3()
          .fromArray(HAND)
          .multiplyScalar(s)
          .toArray();
        root.scale.setScalar(s);
        root.position.y = -box.min.y * s;
        return root;
      })
      .catch((e) => {
        console.warn("[frog] model failed to load", e);
        return null;
      });
  }
  return templatePromise;
}

export function buildMilkFrog() {
  const group = new Group(),
    // 模型是单块网格，迈腿做不了，所以用整体起伏/摇摆代替步态。
    body = new Group(),
    model = new Group(),
    api = {
      group,
      model,
      walk: null,
      gun: null,
      muzzle: null,
      legL: new Object3D(),
      legR: new Object3D(),
      armL: new Object3D(),
      armR: new Object3D(),
    };

  function walk(v) {
    model.position.y = Math.abs(v) * 0.06;
    model.rotation.x = -Math.abs(v) * 0.08;
    model.rotation.z = v * 0.11;
  }

  api.walk = walk;
  (body.rotation.y = Math.PI),
    body.add(model),
    group.add(body),
    loadTemplate().then((t) => {
      if (!t) return;
      model.add(t.clone(!0));
      // 枪握在右手里，枪口朝前略微下压（低持枪位）。
      const gun = createPac9Prop(0.62);
      gun.position.fromArray(t.userData.gunLocal);
      gun.position.z += 0.05;
      gun.rotation.set(0.16, 0.04, 0);
      model.add(gun);
      api.gun = gun;
      api.muzzle = gun.getObjectByName("muzzle") || gun;
    });

  return api;
}
