var bootElement = document.getElementById("boot");

var bootMessage = document.getElementById("boot-msg");

var bootProgress = document.getElementById("boot-fill");

var bootPercent = document.getElementById("boot-percent");

var bootBar = document.getElementById("boot-bar");

var currentProgress = 0;

var yieldToBrowser = () =>
  new Promise((resolve) => requestAnimationFrame(() => resolve()));

async function setBootProgress(i, e) {
  currentProgress = Math.max(currentProgress, Math.min(1, Math.max(0, e)));
  let percent = Math.round(currentProgress * 100);
  (bootMessage && (bootMessage.textContent = i),
    bootPercent && (bootPercent.textContent = percent + "%"),
    bootProgress && (bootProgress.style.width = percent + "%"),
    bootBar && bootBar.setAttribute("aria-valuenow", String(percent)),
    await yieldToBrowser());
}

export {
  bootElement,
  setBootProgress,
  bootMessage,
  bootProgress,
  yieldToBrowser,
};
