// 友军奶蛙：一个持枪的 AI 队友。移动完全沿用噜噜（hound）那套逻辑：
// nav 网格寻路 → 朝向/加减速 → 前方射线避障 → 贴地，靠近目标后停下点射。
import { Vector3 } from "../vendor/three-r180.js";
import { buildMilkFrog } from "./milk-frog.js";
import { createHealthBar, createNameTag } from "../ui/health-bar.js";

const ALLY = {
  runSpeed: 4.2, // 噜噜 runSpeed 4.5，友军略慢
  accel: 7,
  turnRate: 2.8,
  replan: 0.7,
  fireRange: 26,
  holdDist: 9, // 靠到 9m 就停下开火
  followBack: 2.8,
  fireGap: [0.65, 1.05],
  damage: 9,
  barHeight: 2.1,
};

const clamp = (v, a, b) => Math.min(b, Math.max(a, v)),
  angDiff = (a, b) => Math.atan2(Math.sin(a - b), Math.cos(a - b));

export function createAllies(context) {
  const list = [];
  let spawned = !1;

  const probe = new Vector3(),
    rayDir = new Vector3(),
    goalV = new Vector3(),
    aim = new Vector3(),
    dir = new Vector3(),
    muzzleW = new Vector3(),
    fwd = new Vector3(),
    right = new Vector3(),
    slot = new Vector3();

  function groundAt(x, z, y) {
    try {
      return context.physics.groundHeight(x, z, y + 1);
    } catch {
      return y;
    }
  }

  function walkable(x, z) {
    const nav = context.physics && context.physics.nav;
    if (!nav || !nav.isWalkable) return !0;
    try {
      return nav.isWalkable(x, z);
    } catch {
      return !1;
    }
  }

  function createMover(pos) {
    return {
      pos,
      yaw: 0,
      yawRate: 0,
      speed: 0,
      maxSpeed: 0,
      wantYaw: 0,
      goal: new Vector3(),
      hasGoal: !1,
      path: null,
      wp: 0,
      planT: 0,
      push: new Vector3(),
      blocked: !1,
      feelT: 0,
      phase: 0,
      lastPos: new Vector3(),
      stuckT: 0,
      escape: 0,
    };
  }

  function setGoal(m, x, z, force) {
    if (!force && m.hasGoal && m.goal.distanceToSquared(goalV.set(x, m.pos.y, z)) < 1.2)
      return;
    (m.goal.set(x, m.pos.y, z), (m.hasGoal = !0), (m.planT = 0));
  }

  // 噜噜的移动核心：路径跟随 + 转向/加减速 + 射线避障 + 贴地
  function stepMover(m, dt) {
    if (m.hasGoal) {
      m.planT -= dt;
      if (m.planT <= 0) {
        m.planT = ALLY.replan;
        try {
          m.path = context.physics.nav.findPath(m.pos, m.goal);
        } catch {
          m.path = null;
        }
        m.wp = 0;
      }
      let wp = m.goal;
      if (m.path && m.path.length) {
        while (
          m.wp < m.path.length - 1 &&
          Math.hypot(m.path[m.wp].x - m.pos.x, m.path[m.wp].z - m.pos.z) < 0.55
        )
          m.wp++;
        wp = m.path[m.wp];
      }
      const gd = Math.hypot(m.goal.x - m.pos.x, m.goal.z - m.pos.z);
      if (gd < 0.45) (m.hasGoal = !1), (m.maxSpeed = 0);
      else {
        m.wantYaw = Math.atan2(wp.x - m.pos.x, wp.z - m.pos.z);
        const diff = Math.abs(angDiff(m.wantYaw, m.yaw));
        m.maxSpeed =
          diff > 1.1
            ? 0
            : Math.min(ALLY.runSpeed * (1 - diff * 0.5), 0.4 + gd * 2.6);
      }
    } else m.maxSpeed = 0;

    // 转向（方向和噜噜一样：yaw=0 朝 +Z）
    const diff = angDiff(m.wantYaw, m.yaw),
      turn = clamp(diff * 6, -ALLY.turnRate, ALLY.turnRate);
    m.yawRate += (turn - m.yawRate) * (1 - Math.exp(-10 * dt));
    m.yaw += m.yawRate * dt;

    // 加减速
    const a = m.maxSpeed > m.speed ? ALLY.accel : -ALLY.accel * 1.4;
    m.speed = clamp(m.speed + a * dt, 0, Math.max(m.maxSpeed, 0));

    const fx = Math.sin(m.yaw),
      fz = Math.cos(m.yaw);

    // 前方探障
    m.feelT -= dt;
    if (m.feelT <= 0 && m.speed > 0.3) {
      m.feelT = 0.12;
      probe.set(m.pos.x, m.pos.y + 0.55, m.pos.z);
      rayDir.set(fx, 0, fz);
      let hit = null;
      try {
        hit = context.physics.raycast(probe, rayDir, 0.75 + m.speed * 0.12);
      } catch {}
      m.blocked = !!hit;
    } else if (m.speed <= 0.3) m.blocked = !1;

    let nx = m.pos.x + (fx * m.speed + m.push.x) * dt,
      nz = m.pos.z + (fz * m.speed + m.push.z) * dt;

    // 卡住救援：想走却几乎没位移，就短暂无视障碍往外挤，避免永久卡死
    m.stuckT += dt;
    if (m.stuckT > 0.7) {
      (m.stuckT = 0),
        m.speed > 0.35 &&
          m.pos.distanceToSquared(m.lastPos) < 0.05 &&
          (m.escape = 1.2),
        m.lastPos.copy(m.pos);
    }
    m.escape = Math.max(0, m.escape - dt);

    // 当前位置本身已在网格外时不拦截，让它能走出来
    const loose = m.escape > 0 || !walkable(m.pos.x, m.pos.z);
    if (!loose && (!walkable(nx, nz) || m.blocked)) {
      if (walkable(nx, m.pos.z)) nz = m.pos.z;
      else if (walkable(m.pos.x, nz)) nx = m.pos.x;
      else (nx = m.pos.x), (nz = m.pos.z);
      m.speed *= 0.9;
    }

    (m.pos.x = nx),
      (m.pos.z = nz),
      m.push.multiplyScalar(Math.exp(-5 * dt)),
      (m.pos.y = groundAt(m.pos.x, m.pos.z, m.pos.y)),
      (m.phase += m.speed * dt * 2.4);
  }

  function spawn() {
    const frog = buildMilkFrog(),
      bar = createHealthBar({ width: 0.62 }),
      tag = createNameTag({ text: "友军", color: "#7fe0a6", width: 0.95 }),
      a = {
        frog,
        bar,
        tag,
        mover: createMover(new Vector3()),
        yaw: 0,
        hp: 100,
        maxHp: 100,
        cool: 0.6,
        target: null,
      };
    frog.group.name = "frog-ally";
    (context.scene.add(frog.group),
      context.scene.add(bar.sprite),
      context.scene.add(tag.sprite));
    list.push(a);
    return a;
  }

  function spawnAll() {
    if (spawned) return;
    spawned = !0;
    const p =
      (context.player && context.player.pos) ||
      (context.level && context.level.playerStart && context.level.playerStart.pos) ||
      new Vector3();
    const a = spawn();
    a.mover.pos.set(p.x, groundAt(p.x, p.z + 3, p.y), p.z + 3);
    a.mover.yaw = Math.atan2(
      (context.player && -Math.sin(context.player.yaw || 0)) || 0,
      (context.player && -Math.cos(context.player.yaw || 0)) || -1,
    );
  }

  function nearestEnemy(from, range) {
    const es = (context.enemies && context.enemies.list) || [];
    let best = null,
      bd = range * range;
    for (let i = 0; i < es.length; i++) {
      const e = es[i];
      if (!e.alive || e.passive || !e.pos) continue;
      const d = e.pos.distanceToSquared(from);
      if (d < bd) (bd = d), (best = e);
    }
    return best;
  }

  function shoot(a, target) {
    const g = a.frog;
    if (g.muzzle) g.muzzle.getWorldPosition(muzzleW);
    else muzzleW.set(a.mover.pos.x, a.mover.pos.y + 1.05, a.mover.pos.z);
    aim.set(
      target.pos.x + (Math.random() - 0.5) * 0.45,
      target.pos.y + 0.9 + (Math.random() - 0.5) * 0.3,
      target.pos.z + (Math.random() - 0.5) * 0.45,
    );
    dir.copy(aim).sub(muzzleW);
    const dist = dir.length();
    if (dist < 1e-3) return;
    dir.divideScalar(dist);
    try {
      context.fx &&
        context.fx.tracer &&
        context.fx.tracer(muzzleW, aim, {
          color: 0x9fe0ff,
          speed: 240,
          width: 0.03,
        });
    } catch {}
    try {
      context.fx &&
        context.fx.muzzleFlash &&
        context.fx.muzzleFlash(muzzleW, dir, { scale: 0.55 });
    } catch {}
    try {
      target.damage &&
        target.damage(ALLY.damage, aim.clone(), dir.clone(), "body");
    } catch {}
    context.events.emit("ally:fire", { pos: muzzleW, target });
  }

  function update(dt) {
    if (!context.game || context.game.state === "title") {
      for (let i = 0; i < list.length; i++) {
        list[i].frog.group.visible = !1;
        list[i].bar.sprite.visible = !1;
      }
      return;
    }
    spawnAll();
    const p = context.player;
    if (!p || !p.pos) return;
    const a = list[0],
      m = a.mover;

    a.target = nearestEnemy(m.pos, ALLY.fireRange + 8);

    if (a.target) {
      const t = a.target,
        d = m.pos.distanceTo(t.pos),
        aimYaw = Math.atan2(t.pos.x - m.pos.x, t.pos.z - m.pos.z);
      if (d > ALLY.holdDist) {
        // 往目标身边靠（噜噜的追击方式：设目标点 + 寻路）
        const k = 1 - ALLY.holdDist / Math.max(d, 1e-3);
        setGoal(m, m.pos.x + (t.pos.x - m.pos.x) * k, m.pos.z + (t.pos.z - m.pos.z) * k);
        m.wantYaw = aimYaw;
      } else {
        (m.hasGoal = !1), (m.wantYaw = aimYaw);
      }
      // 大致对准才开火
      if (d <= ALLY.fireRange && Math.abs(angDiff(aimYaw, m.yaw)) < 0.4) {
        a.cool -= dt;
        if (a.cool <= 0) {
          shoot(a, t);
          a.cool =
            ALLY.fireGap[0] + Math.random() * (ALLY.fireGap[1] - ALLY.fireGap[0]);
        }
      }
    } else {
      // 没目标就跟着玩家（站在玩家身后偏右）
      const yaw = p.yaw || 0;
      fwd.set(-Math.sin(yaw), 0, -Math.cos(yaw));
      right.set(Math.cos(yaw), 0, -Math.sin(yaw));
      slot
        .copy(p.pos)
        .addScaledVector(fwd, -ALLY.followBack)
        .addScaledVector(right, 1.2);
      setGoal(m, slot.x, slot.z);
    }

    stepMover(m, dt);

    a.frog.group.position.copy(m.pos);
    // 模型朝 -Z，噜噜那套 yaw 是朝 +Z，所以补 π
    a.frog.group.rotation.y = m.yaw + Math.PI;
    a.frog.walk(
      m.speed > 0.25
        ? Math.sin(m.phase * Math.PI) * clamp(m.speed / 6, 0.15, 0.75)
        : 0,
    );

    (a.bar.sprite.position.set(m.pos.x, m.pos.y + ALLY.barHeight, m.pos.z),
      a.bar.set(a.hp / a.maxHp, a.hp > 0),
      a.tag.sprite.position.set(m.pos.x, m.pos.y + ALLY.barHeight + 0.18, m.pos.z),
      (a.tag.sprite.visible = a.hp > 0));
  }

  return { list, update, spawnAll };
}
