// 静态 PAC-9 道具枪：复用玩家武器的几何体（不含第一人称手模/贴花），
// 统一朝 +Z、长度可调，并在枪口处挂一个名为 "muzzle" 的空节点，
// 供角色（噜噜、奶蛙第三人称）当作出生点/挂点。
import {
  Box3,
  Color,
  Group,
  Mesh,
  MeshStandardMaterial,
  Object3D,
  Vector3,
} from "../vendor/three-r180.js";
import { mi, w_ } from "./geometry.js";

let template = null;

function buildTemplate() {
  const parts = w_(),
    mats = {
      ano: [0.0085, 0.009, 0.0105, 0.4, 0.45],
      gun: [0.016, 0.016, 0.0165, 0.5, 0.7],
      poly: [0.0125, 0.0128, 0.0135, 0.62, 0],
      plain: [1, 1, 1, 0.92, 0],
    },
    inner = new Group();

  for (const key in mats) {
    const m = mats[key];
    inner.add(
      new Mesh(
        parts[key],
        new MeshStandardMaterial({
          color: new Color(m[0], m[1], m[2]),
          roughness: m[3],
          metalness: m[4],
          vertexColors: !0,
        }),
      ),
    );
  }

  const box = new Box3().setFromObject(inner),
    size = box.getSize(new Vector3());

  // 归一到单位长度，调用方按需要的枪长缩放即可。
  inner.scale.setScalar(1 / Math.max(size.z, 1e-3));
  inner.position.set(0, 0, 0);

  // 枪管在 -Z 端（mi.muzzle = [0, 0, -0.531]），枪托在 +Z 端。
  const tip = new Object3D();
  tip.name = "muzzle";
  tip.position.set(mi.muzzle[0], mi.muzzle[1], mi.muzzle[2]);
  inner.add(tip);

  // 武器几何体本身朝 -Z，在内层转成 +Z；外层根节点不转，
  // 调用方可以自由设置 rotation（否则会把这里的翻转覆盖掉）。
  inner.rotation.y = Math.PI;
  const root = new Group();
  root.add(inner);
  return root;
}

export function createPac9Prop(length = 0.92) {
  template || (template = buildTemplate());
  const g = template.clone(!0);
  g.scale.setScalar(length);
  g.traverse((o) => {
    if (o.isMesh) ((o.castShadow = !0), (o.receiveShadow = !1), (o.frustumCulled = !1));
  });
  return g;
}
