// 3D 血条：一块始终朝向相机的精灵，画布上画血条底色 + 按比例填充。
import {
  CanvasTexture,
  SRGBColorSpace,
  Sprite,
  SpriteMaterial,
} from "../vendor/three-r180.js";

const W = 256,
  H = 40;

function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, h / 2, w / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.lineTo(x + w - rr, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
  ctx.lineTo(x + w, y + h - rr);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  ctx.lineTo(x + rr, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
  ctx.lineTo(x, y + rr);
  ctx.quadraticCurveTo(x, y, x + rr, y);
  ctx.closePath();
}

export function createHealthBar({ width = 0.8 } = {}) {
  const canvas = document.createElement("canvas");
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext("2d"),
    tex = new CanvasTexture(canvas),
    mat = new SpriteMaterial({
      map: tex,
      transparent: !0,
      depthWrite: !1,
      depthTest: !1,
    }),
    sprite = new Sprite(mat);

  (tex.colorSpace = SRGBColorSpace), (sprite.renderOrder = 20);
  sprite.scale.set(width, (width * H) / W, 1);
  sprite.visible = !1;

  let shown = -1;

  function paint(ratio) {
    const r = Math.max(0, Math.min(1, ratio));
    ctx.clearRect(0, 0, W, H);
    // 底板
    ctx.fillStyle = "rgba(8,10,12,0.74)";
    roundRect(ctx, 2, 2, W - 4, H - 4, 9);
    ctx.fill();
    // 血量
    const pad = 6,
      maxW = W - pad * 2;
    if (r > 0) {
      ctx.fillStyle = r > 0.55 ? "#63e07c" : r > 0.28 ? "#ffc63d" : "#ff4a4a";
      roundRect(ctx, pad, pad, Math.max(3, maxW * r), H - pad * 2, 5);
      ctx.fill();
    }
    // 外描边
    ctx.strokeStyle = "rgba(255,255,255,0.32)";
    ctx.lineWidth = 2;
    roundRect(ctx, 2, 2, W - 4, H - 4, 9);
    ctx.stroke();
    tex.needsUpdate = !0;
  }

  return {
    sprite,
    set(ratio, visible = !0) {
      const r = Math.max(0, Math.min(1, ratio));
      sprite.visible = !!visible && r > 0;
      if (Math.abs(r - shown) > 0.004) (shown = r), paint(r);
    },
  };
}

// 头顶阵营标签：静态文字（友军 / 敌军），同样始终面向相机、穿墙可见。
export function createNameTag({ text, color = "#ff6b52", width = 0.9 } = {}) {
  const W = 256,
    H = 64,
    canvas = document.createElement("canvas");
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext("2d");
  ctx.font = "700 40px 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif";
  // 深色底板保证在任何背景下都清晰
  const tw = ctx.measureText(text).width,
    pw = Math.min(W - 8, tw + 30),
    ph = 50;
  ctx.fillStyle = "rgba(8,10,12,0.62)";
  if (ctx.roundRect) {
    (ctx.beginPath(), ctx.roundRect((W - pw) / 2, (H - ph) / 2, pw, ph, 9), ctx.fill());
  } else ctx.fillRect((W - pw) / 2, (H - ph) / 2, pw, ph);
  ((ctx.textAlign = "center"),
    (ctx.textBaseline = "middle"),
    (ctx.lineWidth = 4),
    (ctx.strokeStyle = "rgba(0,0,0,0.85)"),
    ctx.strokeText(text, W / 2, H / 2 + 1),
    (ctx.fillStyle = color),
    ctx.fillText(text, W / 2, H / 2 + 1));

  const tex = new CanvasTexture(canvas),
    sprite = new Sprite(
      new SpriteMaterial({
        map: tex,
        transparent: !0,
        depthWrite: !1,
        depthTest: !1,
        toneMapped: !1,
      }),
    );
  ((tex.colorSpace = SRGBColorSpace),
    (sprite.renderOrder = 20),
    sprite.scale.set(width, (width * H) / W, 1),
    (sprite.visible = !1));
  return { sprite };
}
